            continue
        corrected, conf_num, conf_den = published
        if conf_num * self.cutoff_den < self.cutoff_num * conf_den:
            continue

        for key in flow.report_keys:
            checked += 1
            if self._compare(corrected, expected):
                passed += 1
            else:
                failed.append(key)

    failed.sort()
    if checked == 0:
        consistent: Optional[bool] = None
    else:
        consistent = passed * self.gamma_den >= checked * self.gamma_num
    return {
        "op": "validate",
        "id": request_id,
        "checked": checked,
        "passed": passed,
        "consistent": consistent,
        "failed": failed,
    }

# ------------------------------------------------------------------
# Replay driver
# ------------------------------------------------------------------
def replay(self, events: Sequence[Dict[str, Any]],
           settings: Dict[str, Any]) -> List[Dict[str, Any]]:
    self.settings = settings
    self.trials = settings["trials"]
    self.epsilon = settings["epsilon"]
    self.seed = settings["seed"]
    cutoff = settings["cutoff"]
    self.cutoff_num, self.cutoff_den = cutoff[0], cutoff[1]
    self.bias = settings["bias"]
    self.tau = settings["tau"]
    gamma = settings["gamma"]
    self.gamma_num, self.gamma_den = gamma[0], gamma[1]
    self.cache_slots = settings["cache_slots"]

    answers: List[Dict[str, Any]] = []
    for event in events:
        op = event.get("op")
        if op == "patch":
            answers.append(self._handle_patch(event))
        elif op == "routes":
            answers.append(self._handle_routes(event))
        elif op == "repair":
            answers.append(self._handle_repair(event))

#!/usr/bin/env python3
"""Single-request JSON entry point for the CrossCheck replay validator."""
import json
import math
import sys

from crosscheck import CrossCheck


def _pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError("duplicate object key")
        result[key] = value
    return result


def _finite_float(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("nonfinite number")
    return value


def _reject_constant(text):
    raise ValueError("nonfinite constant")


def _load_request(data):
    # A UTF-8 BOM is not accepted as a JSON whitespace character.
    if data.startswith(b"\xef\xbb\xbf"):
        raise ValueError("UTF-8 BOM")
    text = data.decode("utf-8")
    return json.loads(
        text,
        object_pairs_hook=_pairs,
        parse_float=_finite_float,
        parse_constant=_reject_constant,
    )


def main():
    try:
        request = _load_request(sys.stdin.buffer.read())
        streams = request["streams"]
        output_streams = []
        for stream in streams:
            engine = CrossCheck(stream["topology"])
            event_answers = engine.replay(stream["events"], stream["settings"])
            output_streams.append({"events": event_answers})
        result = {"streams": output_streams}
        sys.stdout.write(json.dumps(result, separators=(",", ":"),
                                    ensure_ascii=True, allow_nan=False))
        sys.stdout.write("\n")
    except Exception:
        # Invalid JSON (including duplicate keys, invalid UTF-8, BOMs, empty
        # input, and nonfinite constants) has exactly one wire response.
        sys.stdout.write('{"error":"invalid_json"}\n')


if __name__ == "__main__":
    main()
