        snapshot_id = event["id"]
        key = self.identity()
        payload = self.cache.lookup(key)
        hit = payload is not None
        if payload is None:
            payload = self.repairer.compute(self.settings, self.counters,
                                            self.loads(), self.plan is not None)
        # Cache entry, snapshot and this answer never alias each other.
        self.cache.store(key, clone_payload(payload))
        self.snapshots.freeze(snapshot_id, clone_payload(payload))
        return {"op": "repair", "id": snapshot_id, "cache_hit": hit,
                "links": payload["links"], "order": payload["order"],
                "counters": payload["counters"]}

    def validate(self, event):
        snapshot_id = event["id"]
        payload = self.snapshots.get(snapshot_id)
        settings = self.settings
        checked, passed, failed = self.validator.validate(
            payload, self.loads(), settings["cutoff"], settings["bias"],
            settings["tau"])
        if checked == 0:
            consistent = None
        else:
            gamma_num, gamma_den = settings["gamma"]
            consistent = passed * gamma_den >= checked * gamma_num
        return {"op": "validate", "id": snapshot_id, "checked": checked,
                "passed": passed, "consistent": consistent, "failed": failed}

    # ----------------------------------------------------------------- replay
    def replay(self, events, settings):
        self._configure(settings)
        handlers = {"patch": self._event_patch, "routes": self._event_routes,
                    "repair": self.repair, "validate": self.validate}
        return [handlers[event["op"]](event) for event in events]

    def _event_patch(self, event):
        return {"op": "patch", "accepted": self.apply_patch(event)}

    def _event_routes(self, event):
        self.apply_routes(event)
        return {"op": "routes", "accepted": True}


def clone_payload(payload):
    """Deep-enough copy so frozen snapshots cannot be reached by later edits."""
    return {
        "links": [list(row) for row in payload["links"]],
        "order": [list(pair) for pair in payload["order"]],
        "counters": {key: {"corrected": cell["corrected"],
                           "confidence": list(cell["confidence"])}
                     for key, cell in payload["counters"].items()},
    }
